import{c as s,U as a,h as i,l as e}from"./chunks/framework.C0iWzFTI.js";const d="/blog/assets/image-20241216222608433.BGPL1tWx.png",n="/blog/assets/image-20241216222816905.CV1gW4Xf.png",p="/blog/assets/image-20241216230537565.uQcscyY4.png",r="/blog/assets/image-20241216231432834.4XJ9wYcL.png",g=JSON.parse('{"title":"JVM","description":"常用的 JVM 分析命令，以及分析工具的使用","frontmatter":{"title":"JVM","description":"常用的 JVM 分析命令，以及分析工具的使用","date":false,"tag":["JVM"]},"headers":[],"relativePath":"1-基础/JVM/问题分析.md","filePath":"1-基础/JVM/问题分析.md"}'),l={name:"1-基础/JVM/问题分析.md"};function o(h,t,c,k,b,u){return a(),i("div",null,t[0]||(t[0]=[e(`<h2 id="一、常用的命令" tabindex="-1">一、常用的命令 <a class="header-anchor" href="#一、常用的命令" aria-label="Permalink to &quot;一、常用的命令&quot;">​</a></h2><p>我这里准备了一个 SpringBoot 项目，接下来，我将从实际案例，来看一下，下面的这些命令。</p><p>基础环境：JDK 1.8.301</p><h3 id="jps" tabindex="-1">jps <a class="header-anchor" href="#jps" aria-label="Permalink to &quot;jps&quot;">​</a></h3><p>命令的格式</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jps [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">hostId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>主要的选项如下</p><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td>-q</td><td></td></tr><tr><td>-m</td><td>输出虚拟机进程启动时传递给主类的参数</td></tr><tr><td>-l</td><td>输出主类的全名，如果进程执行的是 jar 包，输出 Jar 路径</td></tr><tr><td>-v</td><td>输出虚拟机集成启动的时候的 JVM 参数</td></tr></tbody></table><p>对于这个命令，可以查看一下当前虚拟机运行了那些 Java 进程。</p><p>如果不加任何的参数如下，只能看到进程号</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[coding@hcss-ecs-5718 dubbo-provider]$ jps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">852894 Jps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">852761 jar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>如果需要查看时那个 jar 的时，就需要添加 <code>-l</code> 参数</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[coding@hcss-ecs-5718 dubbo-provider]$ jps -l</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">852761 dubbo-provider-1.0.0-SNAPSHOT.jar</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">852953 sun.tools.jps.Jps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>如果想查看启动的时候携带的 JVM 参数信息可以添加 <code>-v</code></p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[coding@hcss-ecs-5718 dubbo-provider]$ jps -lv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">853071 sun.tools.jps.Jps -Dapplication.home=/home/coding/jdk8 -Xms8m</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">853025 dubbo-provider-1.0.0-SNAPSHOT.jar -Xmx1024m</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="jstat" tabindex="-1">jstat <a class="header-anchor" href="#jstat" aria-label="Permalink to &quot;jstat&quot;">​</a></h3><p>作用：监视虚拟机的各种运行状态</p><p>命令的格式</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jstat [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] vmid [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">s|ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中，interval 表示查询间隔，count 表示查询的次数，如果省略这两个参数，表示只查询一次。我们可以借助于这两个参数分析一下，各分区对象的增长速度。</p><p>主要的选项如下：</p><blockquote><p>-gc ： 监控 Java 堆的状况</p></blockquote><p><img src="`+d+'" alt="image-20241216222608433"></p><p>其中各个参数对应的含义如下：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>S0C</code></td><td>s0 区的容量</td><td><code>MU</code></td><td>方法区使用的大小</td></tr><tr><td><code>S1C</code></td><td>s1 区的容量</td><td><code>CCSC</code></td><td>压缩类空间的大小</td></tr><tr><td><code>S0U</code></td><td>s0 区已经使用的大小</td><td><code>CCSU</code></td><td>压缩类空间的使用大小</td></tr><tr><td><code>S1U</code></td><td>s1 区已经使用的大小</td><td><code>YGC</code></td><td>进行 Young GC 的次数</td></tr><tr><td><code>EC</code></td><td>Eden 区的容量</td><td><code>YGCT</code></td><td>进行 YoungGC 总耗时</td></tr><tr><td><code>EU</code></td><td>Eden 区已经使用的大小</td><td><code>FGC</code></td><td>进行 Full GC 的次数</td></tr><tr><td><code>OC</code></td><td>老年代的容量</td><td><code>FGCT</code></td><td>进行Full GC 总耗时</td></tr><tr><td><code>OU</code></td><td>老年代已经使用的大小</td><td><code>GCT</code></td><td>所有 GC 的总耗时</td></tr><tr><td><code>MC</code></td><td>方法区的大小</td><td></td><td></td></tr></tbody></table><blockquote><p>-gcutil : 监控内容与 -gc 一致，但是输出主要关系的是 占用的 百分比</p></blockquote><p><img src="'+n+`" alt="image-20241216222816905"></p><p>对于统计的指标量，不再是使用当前大小，而是占用的百分比，如 Eden 区占用了 39.44% 的内存</p><h3 id="jmap" tabindex="-1">jmap <a class="header-anchor" href="#jmap" aria-label="Permalink to &quot;jmap&quot;">​</a></h3><p>作用：生成堆转储快照</p><p>命令格式：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jmap [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] pid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常见的选项如下</p><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td>-dump</td><td>生成 Java 快照，格式为：<code>-dump:[live,]format=b,file=&lt;filename&gt;</code></td></tr><tr><td>-heap</td><td>显示 Java 堆的详细信息</td></tr><tr><td>-histo</td><td>显示堆中对象统计信息</td></tr><tr><td>-F</td><td>如果 -dump 没有响应的时候，可以通过这个选项，强制生成 dump 快照</td></tr><tr><td>-finalizerinfo</td><td>显示在 F-Queue 中等待 Filalizer 线程执行 finalize 方法的对象</td></tr></tbody></table><p>比如说，我们可以通过如下的方式，生成快照，借助于 Eclipse mat 工具来进行二次分析</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[coding@hcss-ecs-5718 dubbo-provider]$ jmap -dump:format=b,file=dubbo-provider.bin 853025</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dumping heap to /home/coding/dubbo-provider/dubbo-provider.bin ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Heap dump file created</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[coding@hcss-ecs-5718 dubbo-provider]$</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="jstack" tabindex="-1">jstack <a class="header-anchor" href="#jstack" aria-label="Permalink to &quot;jstack&quot;">​</a></h3><p>作用：用于生成虚拟机当前时刻的线程快照</p><p>命令格式如下：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jstack [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] pid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常用的选项如下：</p><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td>-F</td><td>当正常输出的请求无法响应的时候，强制输出</td></tr><tr><td>-l</td><td>除了显示堆栈之外，显示锁的附加信息</td></tr><tr><td>-m</td><td>如果调用本地方法，可以显示 C++/C 的堆栈</td></tr></tbody></table><p><img src="`+p+'" alt="image-20241216230537565"></p><p>输出结果之中，比较重要的是 nid ，显示为 16进制。比如，我们执行了如下的命令：</p><p><img src="'+r+'" alt="image-20241216231432834"></p><p>我们将 PID 列对应的内容，转为 16 进制，去 jstack 的输出结果之中，找对应的 nid ，我们就能够找到占用 CPU 较高的线程是那个了，这也是分析 CPU 冲高的分析方式之一。</p><h2 id="二、eclipse-mat" tabindex="-1">二、Eclipse mat <a class="header-anchor" href="#二、eclipse-mat" aria-label="Permalink to &quot;二、Eclipse mat&quot;">​</a></h2>',47)]))}const E=s(l,[["render",o]]);export{g as __pageData,E as default};
